// ---------------- SPEECH SETUP ----------------
$scope.recordingState = {};
var recognition;
var activeField = null;
var activeTextTarget = null;
var activeTextProperty = null;
var isFirstRecognitionChunk = true;
var recognitionIsListening = false;
var pendingRecognitionStart = null;
var recognitionStartAttempts = 0;
var pendingRecordingField = null;

function clearPendingRecognitionStart() {
	if (pendingRecognitionStart) {
		clearTimeout(pendingRecognitionStart);
		pendingRecognitionStart = null;
	}
}

function broadcastStopCoversheetSpeech(source) {
	$rootScope.$broadcast('coversheetSpeech:stop', source || 'opd');
}

function applyRecordingUiState(fieldKey, isRecording) {
	if (!fieldKey) {
		return;
	}
	$scope.recordingState[fieldKey] = !!isRecording;
}

function appendTranscript(target, property, transcript) {
	if (!target || !property) {
		return;
	}

	target[property] = (target[property] || '') + transcript + ' ';
}

function ensureRecognition() {
	if (!recognition) {
		$scope.initSpeechRecognition();
	}

	return recognition;
}

function startRecognition(delay) {
	if (!ensureRecognition() || !activeField || recognitionIsListening || pendingRecognitionStart) return;

	if (delay) {
		pendingRecognitionStart = setTimeout(function () {
			pendingRecognitionStart = null;
			startRecognition(0);
		}, delay);
		return;
	}

	try {
		recognition.start();
	} catch (e) {
		if (activeField && recognitionStartAttempts < 6) {
			recognitionStartAttempts++;
			startRecognition(250);
			return;
		}
		stopAllRecordings();
		$scope.$applyAsync();
	}
}

function stopRecognition() {
	clearPendingRecognitionStart();
	recognitionIsListening = false;
	recognitionStartAttempts = 0;
	try {
		if (recognition) {
			recognition.stop();
		}
	} catch (e) {}
}

function toggleScopeRecording(fieldKey, scopeField) {
	if (activeField === fieldKey) {
		stopAllRecordings();
		return;
	}

	stopAllRecordings();
	broadcastStopCoversheetSpeech('opd');
	activeField = fieldKey;
	activeTextTarget = $scope;
	activeTextProperty = scopeField;
	pendingRecordingField = fieldKey;
	isFirstRecognitionChunk = true;
	startRecognition();
}

function toggleObjectRecording(fieldKey, objectName, property) {
	if (!$scope[objectName]) {
		$scope[objectName] = {};
	}

	$scope.startTextRecording($scope[objectName], property, fieldKey);
}

$scope.initSpeechRecognition = function () {
	var SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;

	if (!SpeechRecognition) {
		alert("Speech Recognition not supported");
		return null;
	}

	recognition = new SpeechRecognition();
	recognition.lang = 'en-IN';
	recognition.continuous = true;
	recognition.interimResults = false;

	recognition.onstart = function () {
		recognitionIsListening = true;
		recognitionStartAttempts = 0;
		if (pendingRecordingField) {
			applyRecordingUiState(pendingRecordingField, true);
			pendingRecordingField = null;
			$scope.$applyAsync();
		}
	};

	recognition.onresult = function (event) {
		var transcript = '';

		for (var i = event.resultIndex; i < event.results.length; i++) {
			if (event.results[i].isFinal) {
				transcript += event.results[i][0].transcript;
			}
		}

		if (!transcript) {
			return;
		}

		if (isFirstRecognitionChunk) {
			transcript = transcript.charAt(0).toUpperCase() + transcript.slice(1);
			isFirstRecognitionChunk = false;
		}

		appendTranscript(activeTextTarget, activeTextProperty, transcript);
		$scope.$applyAsync();
	};

	recognition.onend = function () {
		recognitionIsListening = false;
		if (activeField && $scope.recordingState[activeField]) {
			startRecognition();
		}
	};

	recognition.onerror = function (e) {
		console.error("Speech error:", e);
		stopAllRecordings();
		$scope.$applyAsync();
	};

	return recognition;
};

$scope.initSpeechRecognition();

$scope.startTextRecording = function (target, property, recordingKey) {
	var key = recordingKey || property;

	if (activeField === key) {
		stopAllRecordings();
		return;
	}

	stopAllRecordings();
	broadcastStopCoversheetSpeech('opd');
	activeField = key;
	activeTextTarget = target;
	activeTextProperty = property;
	pendingRecordingField = key;
	isFirstRecognitionChunk = true;
	startRecognition();
};

$scope.startbirthHistoryRecording = function () {
	toggleScopeRecording('birthHistory', 'birthHistory');
};

$scope.startvaccinationNotePODRecording = function () {
	toggleScopeRecording('vaccinationNotePOD', 'vaccinationNote');
};

$scope.startdescriptionDevRecordingOPD = function () {
	toggleObjectRecording('descriptionDevOPD', 'travHisData', 'descriptionDev');
};

$scope.startobservationDescOPDRecording = function () {
	toggleObjectRecording('observationDescOPD', 'encounterDetailsObj', 'observationDesc');
};

$scope.startGeneralRecording = function () {
	toggleScopeRecording('general', 'descriptiveExamination');
};

$scope.startSystemicRecording = function () {
	toggleScopeRecording('systemic', 'sysDescriptiveExamination');
};

$scope.startNurseNRecording = function () {
	toggleObjectRecording('nurseN', 'nursingNoteObj', 'template');
};

$scope.startAdvicedInstructionRecording = function () {
	toggleScopeRecording('advicedInstruction', 'advicedInstruction');
};

function stopAllRecordings() {
	angular.forEach($scope.recordingState, function (value, key) {
		$scope.recordingState[key] = false;
	});

	activeField = null;
	activeTextTarget = null;
	activeTextProperty = null;
	pendingRecordingField = null;
	stopRecognition();
}

$rootScope.$on('coversheetSpeech:stop', function (ev, source) {
	if (source !== 'opd') {
		stopAllRecordings();
		$scope.$applyAsync();
	}
});

$scope.$on('$destroy', function () {
	stopAllRecordings();
});

