     	$scope.getActivePackagesList = function()
    	{
     		$scope.activePackagesList = [];
    		$scope.activePackageIds = [];
    		if($scope.encounterDetailsObj !== undefined && $scope.encounterDetailsObj !== null){
                if($scope.encounterDetailsObj.patientId === undefined || $scope.encounterDetailsObj.patientId === null || $scope.encounterDetailsObj.patientId ===''){
                    $scope.encounterDetailsObj.patientId = 0;
                }
            }
            else{
                $scope.encounterDetailsObj.patientId = 0;
            }
    		var URI =BASE_URL + ROOT_URL + "/api/packages/patientId/"+$scope.encounterDetailsObj.patientId+"/encounterId/"+$scope.encounterDetailsObj.encounterId+"/visitTypeId/1";
    		var header = {organisationId: $scope.organizationId,unitId:$scope.unitId,packageId:0};
    		GenericServiceParamHeader.serviceAction("GET", URI, null,NOTIFICATION_MSG_STATUS_FALSE,null,header).then(function(response){
    			if(response.data.status == "success"){
    				$scope.activePackagesList = response.data.listObject;
    			$scope.activePackagesList.forEach(function(value,index){
    				$scope.activePackageIds.push(value.packageId);
    			})
    		}
    		});
    	}
     	$scope.getActivePackagesList();
     	
        $scope.removeTempServicesByIndex = function(index){
    		// var serviceIndex = $scope.servicesListPopup.indexOf(index);
        	$scope.checkOrderDetailsExistOrNot(index);
        	angular.forEach($scope.addedServiceOrdersForDisplay,function(value,idx){
     		 	if(index == idx){
     		 		$scope.totalServiceAmount -= value.finalPrice;
     		 	}
 		    });
    		$scope.addedServiceOrdersForDisplay.splice(index, 1);
    		if($scope.addedServiceOrdersForDisplay.length<=0)
	    	{
	    		$scope.isServiceAdded=false;
	    		$scope.noDoctorSpeciality1=true;
	    		$scope.noDoctorSpeciality=true;
	    		$scope.flag=false;
	    		angular.forEach($scope.specialityList,function(value,idx){
	    			if($scope.flag==false)
	    				{
	    		if(value.specialityId == $scope.treatingDoctorSpecialityId){
					var obj={
							"specialityName":value.specialityName,
							"specialityId":value.specialityId
						}
						$scope.specialityList.push(obj);
					$scope.flag=true;
				}
	    				}
	    	});
	    		
                
                
	    		
	    		var obj=$scope.treatingDoctor;
	    		$scope.doctorListMedication.push(obj);
	    	}
	    	$scope.clinObj.servicePriorityId =1;
    		$scope.radiologyAppointmentList.splice(index, 1);
    		 
    	}
        
      
        
        
        
