													var eDT = moment(value.endDate,"DD-MM-YYYY").toDate();
													var startDT =  moment(sDT).format('YYYY-MM-DD');
													var endDT = moment(eDT).format('YYYY-MM-DD');
													var medicationStartDate1 = moment($scope.medicationObj.medicationStartDate,'YYYY-MM-DD').format($scope.dateFormat.toUpperCase());
													var medicationEndDate1 =moment($scope.medicationObj.medicationEndDate,'YYYY-MM-DD').format($scope.dateFormat.toUpperCase());
