        $scope.getDoctorFavouriteMedicationList = function() {

            $rootScope.startLoader();
            var data = {
                specialityId : $scope.encounterDetailsObj.specialityId,
                doctorId : $scope.encounterDetailsObj.doctorId,
                organizationId : $scope.organizationId,
                unitId : $scope.unitId
            };

            var URI = BASE_URL + ROOT_URL
                    + GETDOCTORFAVOURITEMEDICATIONFORCOVERSHEET;

            GenericServiceParamHeader
            .serviceAction(METHOD_POST, URI, data,
                    NOTIFICATION_MSG_STATUS_FALSE)
            .then(function(response) {
                if (response.data.status == "success") {
                    $scope.favouriteMedicationsFromMaster = response.data.listObject;
                    $rootScope.stopLoader();
                    angular.forEach($scope.favouriteMedicationsFromMaster, function(value){
                        if(value.doctorFavoriteId === undefined || value.doctorFavoriteId === null || value.doctorFavoriteId === 0){
                            value.doctorFavoriteId = value.favouriteMedicationId;
                        }
                    });
                }
                else{
                    $rootScope.stopLoader();
                    growl.warning('Unable to Get Favourite Medications..!');
                }
            });
        }

        $scope.customFilter = function(searchText) {
            return function(item) {
                if (!searchText) return true; // Show all if search text is empty
                searchText = searchText.toLowerCase();
                return item.itemName.toLowerCase().includes(searchText) || item.genericName.toLowerCase().includes(searchText);
            };
        };

