        $scope.getPatientDocumentList = function(obj){

              $rootScope.startLoader();
              var data =
              {
                "patientId":$scope.patientDetails.patientId,
                "unitId":$scope.unitId,
                "organisationId":$scope.organizationId,
                "userId":undefined,
                "visitTypeId":undefined,
                "admissionId":undefined,
              }
              var URI = BASE_URL + ROOT_URL + GET_PATIENT_DOCUMENT_ENCOUNTER;
              BillingGenericService.serviceAction(METHOD_POST, URI, data, NOTIFICATION_MSG_STATUS_FALSE).then(function(response) {
                $scope.patientDocumentList = [];
                if (response.data.status == "success")
                {
                    $scope.patientDocumentList = response.data.listObject;
                    if($scope.patientDocumentList !== undefined && $scope.patientDocumentList !== null && $scope.patientDocumentList.length > 0){
                        var healthAtmDocs = [];
                        angular.forEach($scope.patientDocumentList ,function (value){
                            if(value.documentTypeId !== undefined && value.documentTypeId !== null && value.documentTypeId === 70){
                                healthAtmDocs.push(value);
                            }
                        });
                        $scope.healthATMDocumentList = healthAtmDocs;
                    }

                    $rootScope.stopLoader();
                }
                else if(response.data.status == "error")
                 {
                    $rootScope.stopLoader();
                 }
              });
        }

