         $scope.checkExistingMedicalHistory = function(){
            if(!$scope.isDuplicateAllowed){
                if($scope.medicalHistoryCurrentList !== undefined && $scope.medicalHistoryCurrentList !== null && $scope.medicalHistoryCurrentList.length > 0){
                    if($scope.historyMedicalList !== undefined && $scope.historyMedicalList !== null && $scope.historyMedicalList.length > 0){
                        var exists = false;
                        for (var i = 0; i < $scope.historyMedicalList.length; i++) {
                            var newHistory = $scope.historyMedicalList[i];
                            if(newHistory.patientMedicalHistoryId === undefined || newHistory.patientMedicalHistoryId === null || newHistory.patientMedicalHistoryId === '' ){
                                if(newHistory.diagnosisId !== undefined && newHistory.diagnosisId !== null && newHistory.diagnosisId !== ''){
                                    exists = $scope.medicalHistoryCurrentList.some(function(existingHistory) {
                                      return existingHistory.diagnosisId === newHistory.diagnosisId;
                                    });
                                    if(exists){
                                        $scope.historyName = 'Medical';
                                        $scope.historyOrAllergy = 'History';
                                        $("#historyDuplicateConfirmation").show();
                                        break;
                                    }
//                                    else {
//                                        $scope.historyName = '';
//                                        break;
//                                    }
                                }
                                else if(newHistory.isDiagnosisName !== undefined && newHistory.isDiagnosisName === 'Y'){
                                    if(newHistory.diagnosisNameText !== undefined && newHistory.diagnosisNameText !== null && newHistory.diagnosisNameText !== ''){
                                        exists = $scope.medicalHistoryCurrentList.some(function(existingHistory) {

                                           var existDiagnosisName = existingHistory.diagnosisNameText !== undefined && existingHistory.diagnosisNameText != null && existingHistory.diagnosisNameText !== '' ? existingHistory.diagnosisNameText : existingHistory.diagnosisName;
                                           var existDiagnosisCode = existingHistory.code !== undefined && existingHistory.code != null && existingHistory.code !== '' ? existingHistory.code : existingHistory.diagnosisCode;

                                          return existDiagnosisName.toLowerCase() === newHistory.diagnosisNameText.toLowerCase() &&
                                                 existDiagnosisCode.toLowerCase() === newHistory.diagnosisCode.toLowerCase();
                                        });
                                        if(exists){
                                            $scope.historyName = 'Medical';
                                            $scope.historyOrAllergy = 'History';
                                            $("#historyDuplicateConfirmation").show();
                                            break;
                                        }
//                                        else if(!exists && $scope.historyName === ''){
//                                            $scope.historyName = '';
//                                            break;
//                                        }
                                    }
                                }
                            }
                        }
                        if(!exists && $scope.historyName === ''){
                            $scope.historyName = '';
                            return true;
                        }
                    }
                }
                else{
                    $scope.historyName = '';
                    return true;
                }
            }
            else{
                $scope.historyName = 'Medical';
                return true;
            }
         }

