 $scope.toggleMinimize = function ($event) {
     if ($event) $event.stopPropagation();
     $scope.isMinimized = !$scope.isMinimized;
 };

 $scope.closeVideoModal = function ($event) {

     if ($event) $event.stopPropagation();

     $scope.isVideoModalOpen = false;   // remove wrapper completely
     $scope.videoJoinUrl = null;       // destroy iframe ONLY on close
     $scope.isMinimized = false;
     var cookieWObject = JSON.parse(sessionStorage.getItem('cookieEncounterObject'));
     if (cookieWObject) {
         cookieWObject.isVideoCallInit = false;
         sessionStorage.setItem('cookieEncounterObject', JSON.stringify(cookieWObject));
     }
     if ($scope.endCallFlagReset) {
         $scope.endCallFlagReset();
     }
     setTimeout(function () {
         window.location.reload();
     }, 100);
 };

 /* DRAG LOGIC */
 $scope.startDrag = function (event) {

     if ($scope.isMinimized) return;

     isDragging = true;

     const windowEl = document.querySelector('.video-floating-window');

     offsetX = event.clientX - windowEl.offsetLeft;
     offsetY = event.clientY - windowEl.offsetTop;

     $document.on('mousemove', mouseMove);
     $document.on('mouseup', stopDrag);
 };

 function mouseMove(event) {
     if (!isDragging) return;

     const windowEl = document.querySelector('.video-floating-window');

     windowEl.style.left = (event.clientX - offsetX) + 'px';
     windowEl.style.top = (event.clientY - offsetY) + 'px';
 }

 function stopDrag() {
     isDragging = false;
     $document.off('mousemove', mouseMove);
     $document.off('mouseup', stopDrag);
 }
