$scope.drug_list = [];
$scope.checkDrugInteraction = function () {

    $rootScope.startLoader(); // if you are using loader

	 let medicationObj = {};
	let formattedStartDate = $scope.formatDate($scope.medicationObj1.medicationStartDate);
	let formattedEndDate =$scope.formatDate($scope.medicationObj1.medicationEndDateFormatted);

	console.log("formattedStartDate ",formattedStartDate);
	console.log("formattedEndDate ",formattedEndDate);

	medicationObj['medicationStartDate'] = formattedStartDate
	medicationObj['medicationEndDate'] = formattedEndDate
	medicationObj['quantity'] = $scope.medicationObj1.quantity;
	medicationObj['genericName'] = $scope.medicationObj1.genericName;
	medicationObj['itemName'] = $scope.medicationObj1.itemName;
	medicationObj['frequencyDesc'] = $scope.medicationObj1.frequencyDesc;

	$scope.drug_list.push(medicationObj);

    $.ajax({
        url: "https://aidata.axonichealth.com/cdss/parallel",
        method: "POST",
        contentType: "application/json",
        data: JSON.stringify({
            input_data: {
                drug_list: $scope.drug_list,
                newelyAdded: [],
                detailed: "yes",
                patient_context: null
            }
        }),
        success: function (response) {

            $rootScope.stopLoader();
			console.log("API Success:", response);

			var res = response;

			var newDiv = document.getElementById("drugTodrug-text-div");

			// clear old content
			newDiv.innerHTML = "";

			// apply styles
			newDiv.style.whiteSpace = 'pre-line';
			newDiv.style.height = '377px';
			newDiv.style.overflowY = "scroll";

			// set response HTML
			newDiv.innerHTML = res.html;

			// make editable
			newDiv.setAttribute('contenteditable', 'true');

			// open modal
			$scope.showDrugInteractionModal(res);


        },
        error: function (error) {

            $rootScope.stopLoader();

            console.error("API Error:", error);
        }
    });

};

