     $scope.aiSummaryFromAIcosulatation = null;

$scope.getAISummaryData = function () {

    var cookieWObject =
        JSON.parse(sessionStorage.getItem('cookieEncounterObject'));

    var data = {
        appointmentId: cookieWObject.appointmentId
    };

    var URI = BASE_URL + ROOT_URL
        + "/api/opd/getAISummaryData";

    console.log("REQUEST DATA :", data);
    console.log("REQUEST URI :", URI);

     GenericService
        .serviceAction("POST", URI, data)
        .then(function (response) {

            console.log("API RESPONSE :", response);

            if (response.data.status == "success"
                && response.data.object != null) {


                var parsedResponse =
                    JSON.parse(response.data.object);

					console.log(
                    "AI Summary parsedResponse  :",
					parsedResponse
                );


                $scope.aiSummaryFromAIcosulatation =
                    parsedResponse.consultationSummary
                        .replace(/\*\*/g, "").replace(/\n/g, "<br>");

                console.log(
                    "AI Summary :",
                    $scope.aiSummaryFromAIcosulatation
                );

				document.getElementById("aiSummaryFromAIcosulatation").innerHTML =
    $scope.aiSummaryFromAIcosulatation;
            }

            return response;

        }, function (error) {

            console.log("API ERROR :", error);

        });

};

